// Demo loader: a few inbound mails. In production this node is replaced by an
// IMAP / Gmail trigger. The full synthetic corpus lives in data/sample_mails.json.
const SYSTEM = "Tu es l'assistant de triage du service client / ADV d'un vendeur de cuisines. On te donne un mail entrant. Classe-le dans EXACTEMENT une de ces categories: demande_devis, relance_devis, reclamation, demande_information, suivi_commande, annulation, spam, autre. Extrais les champs cles s'ils sont presents (order_ref, quote_ref, budget, contact), sinon null, n'invente rien. Resume en une phrase et propose une action concrete. Reponds UNIQUEMENT par un objet JSON {category, fields:{order_ref,quote_ref,budget,contact}, summary, proposed_action, confidence}. confidence entre 0 et 1.";
const mails = [
  { id: 'm1', from: 'claire.durand@example.com', subject: 'Demande de devis cuisine', body: "Bonjour, nous avons visite votre magasin samedi. Pourriez-vous m'etablir un devis pour la cuisine modele Lina en 3m20 ? Budget environ 8000 euros. Claire Durand, 06 12 34 56 78." },
  { id: 'm3', from: 'sophie.leroy@example.com', subject: 'Probleme porte de meuble cassee', body: 'Bonjour, la cuisine a ete installee mardi mais une porte est fendue et un tiroir ne coulisse pas. Je demande une intervention rapide. Commande CDE-77831. Sophie Leroy.' },
  { id: 'm6', from: 'newsletter@fournisseur-pub.example', subject: 'Offres pros -30%', body: 'Profitez de -30% sur nos plans de travail ce mois-ci. Cliquez pour le catalogue pro.' }
];
return mails.map(m => ({ json: { id: m.id, from: m.from, subject: m.subject, body: m.body, anthropicBody: { model: 'claude-opus-4-8', max_tokens: 512, system: SYSTEM, messages: [ { role: 'user', content: 'Sujet: ' + m.subject + '\n\n' + m.body } ] } } }));

// Deterministic routing (business rules stay auditable; the LLM only understands).
const ROUTE = { demande_devis: 'ADV / Commercial', relance_devis: 'ADV / Commercial', annulation: 'ADV', suivi_commande: 'ADV / Logistique', demande_information: 'Commercial', reclamation: 'SAV', spam: 'Archivage', autre: 'Tri manuel' };
const text = ($json.content && $json.content[0]) ? $json.content[0].text : '{}';
let p;
try { p = JSON.parse(text); } catch (e) { p = { category: 'autre', fields: {}, summary: '', proposed_action: '', confidence: 0 }; }
const src = $('Charger les mails').item.json;
return [{ json: { id: src.id, from: src.from, subject: src.subject, category: p.category, route: ROUTE[p.category] || 'Tri manuel', fields: p.fields, summary: p.summary, proposed_action: p.proposed_action, confidence: p.confidence } }];
